-- PASO 1: Eliminar casilleros de prueba con formato PK-XXXX-US
DELETE FROM users WHERE "lockerCode" LIKE '%-US';

-- PASO 2: Insertar casilleros históricos con formato PAKKIXXXXX

ON CONFLICT (id) DO NOTHING;

-- Verificar cuantos usuarios quedaron en total:
SELECT COUNT(*) AS total_usuarios FROM users;
